package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.tob.*;import io.xeros.content.minigames.tob.instance.*;import io.xeros.content.minigames.tob.rooms.*;import io.xeros.content.minigames.tob.bosses.*;import io.xeros.content.item.lootable.impl.TheatreOfBloodChest;import io.xeros.content.combat.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.GameItem;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class TobSoloPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("tob65qa");p.setDisplayName("Tob65qa");p.getCollectionLog().setSaveName("tob65qa");p.getHealth().setMaximumHealth(100000);p.getHealth().reset();return p;}static void tick(Player p,int n){BossSpecialRoutesCheck.tick(p,n);}static void clear(Player p){if(p.getInstance()!=null)p.getInstance().remove(p);for(NPC n:new ArrayList<>(Arrays.asList(NPCHandler.npcs)))if(n!=null&&n.isUnregister())n.processDeregistration();BossesPlayableCheck.clear(p);}
 static void force(int id)throws Exception{List<GameItem> list=TheatreOfBloodChest.getRareDrops();Field f=TheatreOfBloodChest.class.getDeclaredField("items");f.setAccessible(true);Map<?,?> table=(Map<?,?>)f.get(null);List<GameItem> rare=(List<GameItem>)table.get(io.xeros.content.item.lootable.LootRarity.RARE);int found=-1;for(int i=0;i<rare.size();i++)if(rare.get(i).getId()==id){found=i;break;}ok(found>=0,"Rare fixture");final int index=found;f=TheatreOfBloodChest.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(null,(IntUnaryOperator)(b->b==9?0:index));}
 static void kill(Player p,NPC n){if(n instanceof PestilentBloat){for(int i=0;i<60&&!n.canBeDamaged(p);i++)n.process();ok(n.canBeDamaged(p),"Bloat never sleeps");}for(int phase=0;phase<4&&!n.isDead();phase++){n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);if(!n.isDead())tick(p,6);}ok(n.isDead(),"Cannot kill boss "+n.getName());for(int i=0;i<45&&!n.needRespawn&&!n.isUnregister();i++)n.process();ok(n.needRespawn||n.isUnregister(),"Corpse stuck "+n.getName());}
 static void complete(boolean full)throws Exception{Player p=actor();if(full)while(p.getItems().freeSlots()>0)ok(p.getItems().addItem(526,1),"Full bag");force(22325);ok(TobInstance.enterSolo(p),"Solo ToB entry");tick(p,1);TobInstance raid=(TobInstance)p.getInstance();raid.moveToNextRoom(p);ok(raid.getRoomIndex()==0,"Gate bypass");for(int room=0;room<6;room++){ok(raid.getRoomIndex()==room,"Wrong room "+room+" actual="+raid.getRoomIndex());List<NPC> bosses=new ArrayList<>(raid.getNpcs());ok(!bosses.isEmpty(),"Empty room "+room);for(NPC n:bosses)if(!n.isDead()&&!n.isUnregister())kill(p,n);tick(p,7);}ok(raid.getRoomIndex()==6&&p.tobCompletions==1&&p.getItems().getItemCount(22325,false)==1,"ToB completion/reward");int gold=p.getItems().getItemCount(995,false);RoomSevenTreasure.openChest(p,raid);TheatreOfBloodChest.rewardItems(p,List.of(new GameItem(22325)));ok(p.getItems().getItemCount(22325,false)==1&&p.getItems().getItemCount(995,false)==gold,"Duplicate chest");ok(p.getCollectionLog().getCollections().values().stream().flatMap(List::stream).anyMatch(i->i.getId()==22325),"Scythe collection log");ok(PlayerSave.saveGameInstant(p),"ToB save");Player q=actor();ok(PlayerSave.loadGame(q,"tob65qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.tobCompletions==1&&q.getItems().getItemCount(22325,false)==1&&q.getTeleportToX()==TobConstants.FINISHED_TOB_POSITION.getX()&&q.heightLevel==0,"ToB reward/KC/safe reload");PlayerHandler.players[1]=p;clear(p);clear(q);System.out.println("TOB_SOLO_SIX_NATIVE_ROOMS_BLOAT_SLEEP_NYLOCAS_VERZIK_TRANSFORM_REAL_DEATHS_AUTOPROGRESSION_SCYTHE_EXACT_COLLECTION_SINGLE_CHEST_KC_AND_SAVE_RELOAD_PASS");}
 static void safety(){Player p=actor();TheatreOfBloodChest.rewardItems(p,List.of(new GameItem(22325)));ok(p.getItems().getItemCount(22325,false)==0,"Unplayed reward");p.isDead=true;ok(!TobInstance.enterSolo(p),"Dead ToB entry");clear(p);p=actor();ok(TobInstance.enterSolo(p),"Entry");tick(p,1);ok(!TobInstance.enterSolo(p),"Duplicate ToB");TobInstance raid=(TobInstance)p.getInstance();RoomSevenTreasure.openChest(p,raid);ok(p.getItems().getItemCount(22325,false)==0,"Early chest");p.isDead=true;p.getHealth().setCurrentHealth(0);io.xeros.content.combat.death.PlayerDeath.giveLife(p);ok(p.getInstance()==null&&raid.isDisposed()&&p.getHealth().getCurrentHealth()>0&&p.tobCompletions==0,"Solo defeat cleanup");clear(p);System.out.println("TOB_SOLO_EARLY_REWARD_DEAD_DUPLICATE_ENTRY_GUARDS_AND_PLAYER_DEATH_DISPOSAL_RESPAWN_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;complete(false);complete(true);safety();System.out.println("TOB_SOLO_PLAYABLE_V65_PASS");System.exit(0);}
}
